const sqliteRegistryEntryApproved = `-- name: RegistryEntryApproved :one
-- Whether the registry entry at a path is indexed with the content sha256 and
-- has an approval of it; no row when the path is not an entry.
SELECT a.sha256 IS NOT NULL AND e.sha256 = @sha256 AS approved FROM registry_entries e
LEFT JOIN approvals a ON a.repo_key = e.repo_key AND a.path = e.path AND a.sha256 = e.sha256
WHERE e.repo_key = @repo_key AND e.path = @path;`

const sqliteReleaseBlobs = `-- name: ReleaseBlobs :exec
-- Drops one reference per array element (duplicates count). The digests
-- come as a JSON array.
UPDATE blobs
SET refcount = blobs.refcount - r.n,
    unreferenced_since = CASE WHEN blobs.refcount - r.n = 0 THEN strftime('%Y-%m-%d %H:%M:%f000+00:00', 'now') END
FROM (SELECT value AS sha256, count(*) AS n FROM json_each(CAST(@sha256s AS TEXT)) GROUP BY value) AS r
WHERE blobs.sha256 = r.sha256;`

