func (q *sqliteQueries) BlobDeleting(ctx context.Context, arg string) (bool, error) {
	var i bool

	rows, err := q.query(ctx, "BlobDeleting", nil, sqliteBlobDeleting, sql.Named("sha256", arg))
	if err != nil {
		return i, err
	}

	defer rows.Close()

	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return i, err
		}

		return i, sql.ErrNoRows
	}

	err = rows.Scan(&i)

	return i, err
}

func (q *sqliteQueries) BlobStats(ctx context.Context) (BlobStatsRow, error) {
	var i BlobStatsRow

	rows, err := q.query(ctx, "BlobStats", []string{"blobs", "bytes", "unreferencedblobs", "unreferencedbytes"}, sqliteBlobStats)
	if err != nil {
		return i, err
	}

	defer rows.Close()

	if !rows.Next() {
		if err := rows.Err(); err != nil {
			return i, err
		}

		return i, sql.ErrNoRows
	}

	err = rows.Scan(&i.Blobs, &i.Bytes, &i.UnreferencedBlobs, &i.UnreferencedBytes)

	return i, err
}

func (q *sqliteQueries) BuildsProducing(ctx context.Context, arg string) ([]BuildsProducingRow, error) {
	rows, err := q.query(ctx, "BuildsProducing", []string{"project", "name", "number", "started", "moduleid"}, sqliteBuildsProducing, sql.Named("sha1", arg))
	if err != nil {
		return nil, err
	}

	defer rows.Close()

	items := []BuildsProducingRow{}

	for rows.Next() {
		var i BuildsProducingRow
		if err := rows.Scan(&i.Project, &i.Name, &i.Number, sqliteTimeScanner{&i.Started}, &i.ModuleID); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Close(); err != nil {
		return nil, err
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}

