func (q *sqliteQueries) UserGroups(ctx context.Context, arg string) ([]UserGroupsRow, error) {
	rows, err := q.query(ctx, "UserGroups", []string{"name", "admin", "viewer"}, sqliteUserGroups, sql.Named("username", arg))
	if err != nil {
		return nil, err
	}

	defer rows.Close()

	items := []UserGroupsRow{}

	for rows.Next() {
		var i UserGroupsRow
		if err := rows.Scan(&i.Name, &i.Admin, &i.Viewer); err != nil {
			return nil, err
		}

		items = append(items, i)
	}

	if err := rows.Close(); err != nil {
		return nil, err
	}

	if err := rows.Err(); err != nil {
		return nil, err
	}

	return items, nil
}
